-- CANDIDATE ONLY. One explicit reviewed phase, no auto apply.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $preflight$ DECLARE f record; h text; BEGIN
 IF (SELECT md5(pg_get_functiondef(to_regprocedure('public.create_my_specialist_draft(text,text,text,text,text,text)')))) IS DISTINCT FROM '64f33fb6fd83f891363c2035f39ca73c' THEN RAISE EXCEPTION 'Core function drift: create_my_specialist_draft(text,text,text,text,text,text)'; END IF;
 IF has_function_privilege('anon','public.create_my_specialist_draft(text,text,text,text,text,text)','EXECUTE') OR NOT has_function_privilege('authenticated','public.create_my_specialist_draft(text,text,text,text,text,text)','EXECUTE') OR NOT has_function_privilege('service_role','public.create_my_specialist_draft(text,text,text,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Core ACL drift'; END IF;
 IF (SELECT md5(pg_get_functiondef(to_regprocedure('public.get_my_specialists()')))) IS DISTINCT FROM '82a3057d27c450b18cbb00edc393db78' THEN RAISE EXCEPTION 'Core function drift: get_my_specialists()'; END IF;
 IF has_function_privilege('anon','public.get_my_specialists()','EXECUTE') OR NOT has_function_privilege('authenticated','public.get_my_specialists()','EXECUTE') OR NOT has_function_privilege('service_role','public.get_my_specialists()','EXECUTE') THEN RAISE EXCEPTION 'Core ACL drift'; END IF;
 IF (SELECT md5(pg_get_functiondef(to_regprocedure('public.update_my_specialist_draft(uuid,text,text,text,text,text)')))) IS DISTINCT FROM '630a01e05cb0f65cbef110ef4a695e79' THEN RAISE EXCEPTION 'Core function drift: update_my_specialist_draft(uuid,text,text,text,text,text)'; END IF;
 IF has_function_privilege('anon','public.update_my_specialist_draft(uuid,text,text,text,text,text)','EXECUTE') OR NOT has_function_privilege('authenticated','public.update_my_specialist_draft(uuid,text,text,text,text,text)','EXECUTE') OR NOT has_function_privilege('service_role','public.update_my_specialist_draft(uuid,text,text,text,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Core ACL drift'; END IF;
 IF NOT EXISTS(SELECT FROM pg_class WHERE oid='public.specialist_profiles'::regclass AND relrowsecurity AND relforcerowsecurity) OR has_table_privilege('anon','public.specialist_profiles','SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated','public.specialist_profiles','SELECT,INSERT,UPDATE,DELETE') THEN RAISE EXCEPTION 'Profile RLS/ACL drift'; END IF;
 SELECT md5(string_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull::text||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),''),'|' ORDER BY a.attnum)) INTO h FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.specialist_profiles'::regclass AND a.attnum>0 AND NOT a.attisdropped; IF h IS DISTINCT FROM 'c23c3734b1e68f6a85376709caf424c4' THEN RAISE EXCEPTION 'Profile columns drift'; END IF;
 SELECT md5(string_agg(conname||':'||pg_get_constraintdef(oid),'|' ORDER BY conname)) INTO h FROM pg_constraint WHERE conrelid='public.specialist_profiles'::regclass; IF h IS DISTINCT FROM '7d5e75a8d743b97ff126103a499b78ab' THEN RAISE EXCEPTION 'Profile constraints drift'; END IF;
 SELECT md5(coalesce(string_agg(row_to_json(p)::text,'|' ORDER BY schemaname,tablename,policyname),'')) INTO h FROM pg_policies p WHERE schemaname='storage'; IF h IS DISTINCT FROM 'e4457759b69f625549d7c6b73787125f' THEN RAISE EXCEPTION 'Storage policies drift'; END IF;
 IF EXISTS(SELECT FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('specialist_services','specialist_settings','specialist_media','specialist_channel_sets','specialist_contact_channels','specialist_upload_reservations','specialist_upload_control')) OR EXISTS(SELECT FROM storage.buckets WHERE id='specialist-media') THEN RAISE EXCEPTION 'Not pristine production baseline; do not retry/overwrite'; END IF;
END $preflight$;
NOTIFY pgrst,'reload schema';
COMMIT;
